export interface TelegramEmojiItem {
  emoji: string;
  src: string;
}

export interface TelegramEmojiCategory {
  id: string;
  label: string;
  items: TelegramEmojiItem[];
}

function normalizeTelegramEmojiSrc(src: string): string {
  // Vite copies public/ to dist root, so /telegram-emoji/... resolves correctly
  return src;
}

